oxy_webhelp_navlinks = {"plan_orchestrated_recovery-d39307e55609":{"topics":[{"title":"Evaluate your recovery options","shortdesc":"<p class=\"shortdesc\">Understanding the available recovery types and approaches for <span class=\"ph\">Orchestrated Recovery<\/span>         helps determine the right fit for a given environment and recovery objectives.<\/p>","href":"saas\/oar_evaluate_recovery_options.html","attributes":{"data-id":"oar_evaluate_recovery_options"},"menu":{"hasChildren":false},"tocID":"oar_evaluate_recovery_options-d39307e55626","topics":[]},{"title":"Planning checklist for <span class=\"ph\">Orchestrated Recovery<\/span>","shortdesc":"<p class=\"shortdesc\">You can use this checklist to confirm the prerequisites and configuration         decisions for a <span class=\"ph\">Recovery Plan<\/span> before you create one.<\/p>","href":"saas\/oar_planning_checklist.html","attributes":{"data-id":"oar_planning_checklist"},"menu":{"hasChildren":false},"tocID":"oar_planning_checklist-d39307e55640","topics":[]},{"title":"RBAC for <span class=\"ph\">Orchestrated Application Recovery<\/span>","shortdesc":"<p class=\"shortdesc\">Viewing and managing <span class=\"ph\">Recovery Plans<\/span> and recoveries in <span class=\"ph\">Orchestrated Recovery<\/span> require RBAC privileges.<\/p>","href":"saas\/rbac_orchestrated_recovery.html","attributes":{"data-id":"rbac_orchestrated_recovery"},"menu":{"hasChildren":false},"tocID":"rbac_orchestrated_recovery-d39307e55656","topics":[]},{"title":"Supported operating systems for IP reconfiguration","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">Orchestrated Application Recovery<\/span> supports static IP reconfiguration for specific         operating systems during VMware virtual machine recovery. This topic covers static IP         reconfiguration only; <span class=\"ph\">Orchestrated Application Recovery<\/span> supports recovery orchestration for all         operating systems supported by the underlying hypervisor.<\/p>","href":"saas\/orchestrated_recovery_operating_systems.html","attributes":{"data-id":"orchestrated_recovery_operating_systems"},"menu":{"hasChildren":false},"tocID":"orchestrated_recovery_operating_systems-d39307e55675","topics":[]},{"title":"Supported replication targets for failover operations","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> supports specific types of replication targets for failover         operations.<\/p>","href":"saas\/supported_rep_targets_for_failover.html","attributes":{"data-id":"supported_rep_targets_for_failover"},"menu":{"hasChildren":false},"tocID":"supported_rep_targets_for_failover-d39307e55691","topics":[]},{"title":"Sizing, RTO, and RPO","shortdesc":"<p class=\"shortdesc\">Recovery time objective (RTO) and recovery point objective (RPO) for <span class=\"ph\">Orchestrated Recovery<\/span> recoveries depend on your SLA Domain configuration and the         RTO optimization method you select when creating a VMware disaster <span class=\"ph\">Recovery Plan<\/span>.<\/p>","href":"saas\/oar_sizing_rto_rpo.html","attributes":{"data-id":"oar_sizing_rto_rpo"},"menu":{"hasChildren":false},"tocID":"oar_sizing_rto_rpo-d39307e55704","topics":[]},{"title":"Pre-seeding disks for disaster recovery","shortdesc":"<p class=\"shortdesc\">Pre-seeding disks reduces failover time for VMware disaster <span class=\"ph\">Recovery Plans<\/span> by         maintaining a warm-standby copy of each protected virtual machine in the target datastore         before a disaster occurs.<\/p>","href":"saas\/oar_preseeding_disks.html","attributes":{"data-id":"oar_preseeding_disks"},"menu":{"hasChildren":false},"tocID":"oar_preseeding_disks-d39307e55721","topics":[]}]}};